// The complaint number in the act (docs/architecture.md §8.2, ADR-0015): `R-AAAA-NNNNNN`, correlative
// per world, epoch and year of the world clock, generated by code. ONE `TransactWriteItems` writes
// the counter (`n − 1 → n`, conditional on the value read), the complaint, its `FILED` register entry
// (with the chain head), the three SLA milestone timers, the idempotency claim `IDEMP#REGISTER#<eventId>`
// and the audit entry: number, entry and complaint exist together or not at all. A cancelled
// transaction re-reads and retries (no gap); a repeat of the same event finds the claim and gets the
// same number back.
import { type Channel, type ComplaintOrigin, type ComplaintType, type PresentationKind, ToolError, complaintNumber } from "@reclamo/shared";
import type { Actor } from "../domain/common";
import type { Complaint, ComplaintSubject, Control, Priority } from "../domain/complaint";
import type { RegisterEntry } from "../domain/ledger";
import type { NewOf } from "../connector/codec";
import { maskSensitive } from "../lib/mask";
import { type ComplaintsDeps, newIdOf, realNowOf } from "./deps";
import { appendChained } from "./register";
import { MILESTONE_ORDER, deadlineText, milestoneTimerId, milestoneTimers, simYearAr, slaPlan } from "./sla";

/** Source of the idempotency claim of a registration (`IDEMP#REGISTER#<eventId>`). */
export const REGISTER_IDEMPOTENCY = "REGISTER";

export interface RegistrationInput {
  readonly worldId: string;
  readonly customerId: string;
  readonly kind: PresentationKind;
  readonly type: ComplaintType;
  readonly channel: Channel;
  /** One sentence; masked here before it is stored. */
  readonly summary: string;
  readonly subject?: ComplaintSubject;
  readonly sourceMessageId?: string;
  /** The event that registers it (inbound message, tool call): one number per event. */
  readonly eventId: string;
  /** The presenter's document as the core masks it (BCRA 3.1.3 minimum data in `FILED`). */
  readonly presenter: { readonly docType: string; readonly docNumberMasked: string };
  /** Simulated instant of the presentation (the world clock at the event). */
  readonly filedAtSim: string;
  readonly holidays: readonly string[];
  readonly actor: Actor;
  readonly origin?: ComplaintOrigin;
  readonly priority?: Priority;
  /** Mirror of the conversation's control at filing. */
  readonly control?: Control;
}

export interface Registration {
  readonly complaint: Complaint;
  /** False when this event had already registered it (same number back). */
  readonly created: boolean;
  readonly deadlineText: string;
  /** `hash` of the `FILED` entry, printed on the acknowledgement PDF. */
  readonly filedHash?: string;
}

/** A consulta is always an information request, and only a consulta is one (docs/design-brief.md §4). */
export function assertKindAndType(kind: PresentationKind, type: ComplaintType): void {
  if ((kind === "CONSULTA") !== (type === "INFORMATION_REQUEST")) throw new ToolError("INVALID", "a CONSULTA is registered as INFORMATION_REQUEST, and only a CONSULTA is");
}

class AlreadyRegistered extends Error {
  constructor(readonly complaintId: string) {
    super("already registered by this event");
  }
}

async function existingRegistration(deps: ComplaintsDeps, worldId: string, eventId: string): Promise<Registration | undefined> {
  const claim = await deps.connector.claims.getIdempotency(worldId, REGISTER_IDEMPOTENCY, eventId);
  const complaintId = claim?.result?.complaintId;
  if (typeof complaintId !== "string") return undefined;
  return registrationOf(deps, worldId, complaintId);
}

async function registrationOf(deps: ComplaintsDeps, worldId: string, complaintId: string): Promise<Registration> {
  const complaint = await deps.connector.complaints.get(worldId, complaintId, { consistent: true });
  if (!complaint) throw new ToolError("UNAVAILABLE", "registered complaint not readable yet");
  const [filed] = await deps.connector.chains.listRegisterByComplaint(worldId, complaint.epoch, complaint.complaintNumber);
  return { complaint, created: false, deadlineText: deadlineText(complaint.deadlineSim), ...(filed ? { filedHash: filed.hash } : {}) };
}

/** Registers a presentation with its number, `FILED` entry and milestones in one transaction. */
export async function registerComplaint(deps: ComplaintsDeps, input: RegistrationInput): Promise<Registration> {
  assertKindAndType(input.kind, input.type);
  const { connector } = deps;
  const known = await existingRegistration(deps, input.worldId, input.eventId);
  if (known) return known;
  const epoch = await connector.counters.getEpoch(input.worldId);
  if (epoch < 1) throw new ToolError("NOT_FOUND", "world not found");
  const year = simYearAr(input.filedAtSim);
  const complaintId = newIdOf(deps, "cmp");
  const plan = slaPlan(input.filedAtSim, input.holidays);
  const summary = maskSensitive(input.summary).slice(0, 200);
  let complaint: Complaint | undefined;

  try {
    const register = await appendChained(deps, {
      chain: "REG",
      worldId: input.worldId,
      epoch,
      build: async ({ attempt }) => {
        if (attempt > 0) {
          const claim = await connector.claims.getIdempotency(input.worldId, REGISTER_IDEMPOTENCY, input.eventId);
          if (typeof claim?.result?.complaintId === "string") throw new AlreadyRegistered(claim.result.complaintId);
        }
        const current = await connector.counters.getComplaintCounter(input.worldId, epoch, year);
        const number = complaintNumber(year, current + 1);
        const value: NewOf<typeof Complaint> = {
          worldId: input.worldId,
          complaintId,
          complaintNumber: number,
          epoch,
          customerId: input.customerId,
          kind: input.kind,
          type: input.type,
          status: "REGISTERED",
          priority: input.priority ?? "NORMAL",
          origin: input.origin ?? "LIVE",
          control: input.control ?? "AGENT",
          channel: input.channel,
          summary,
          ...(input.subject ? { subject: input.subject } : {}),
          ...(input.sourceMessageId ? { sourceMessageId: input.sourceMessageId } : {}),
          filedAtSim: input.filedAtSim,
          deadlineSim: plan.deadlineSim,
          slaState: "ON_TIME",
          emailAnswerConsent: { status: "PENDING" },
          statusHistory: [{ from: null, to: "REGISTERED", atSim: input.filedAtSim, cause: "FILED", actor: input.actor }],
        };
        complaint = { ...value, version: 1 } as Complaint;
        const timers = milestoneTimers({ worldId: input.worldId, epoch, complaintId, complaintNumber: number, plan });
        const entry: Omit<NewOf<typeof RegisterEntry>, "worldId" | "epoch" | "seq" | "prevHash" | "hash" | "atReal"> = {
          eventType: "FILED",
          atSim: input.filedAtSim,
          complaintId,
          complaintNumber: number,
          kind: input.kind,
          type: input.type,
          channel: input.channel,
          origin: value.origin,
          presenter: input.presenter,
          status: "REGISTERED",
          reason: summary,
        };
        return {
          entry,
          extra: [
            connector.counters.advanceComplaintCounterOp(input.worldId, epoch, year, current),
            connector.complaints.createOp(value),
            ...timers.map((timer) => connector.timers.putOp(timer)),
            connector.claims.idempotencyOp(input.worldId, REGISTER_IDEMPOTENCY, input.eventId, { complaintId, complaintNumber: number }),
            connector.audit.appendOp({
              worldId: input.worldId,
              epoch,
              auditId: newIdOf(deps, "aud"),
              ts: realNowOf(deps).toISOString(),
              atSim: input.filedAtSim,
              action: "COMPLAINT_REGISTERED",
              actor: input.actor,
              refs: { complaintId, complaintNumber: number, eventId: input.eventId },
              primaryRef: `CMP#${complaintId}`,
              outcome: "REGISTERED",
            }),
          ],
        };
      },
    });
    await scheduleMilestones(deps, input.worldId, complaintId);
    const stored = complaint as Complaint;
    return { complaint: stored, created: true, deadlineText: deadlineText(stored.deadlineSim), filedHash: register.entry.hash };
  } catch (error) {
    if (error instanceof AlreadyRegistered) return registrationOf(deps, input.worldId, error.complaintId);
    throw error;
  }
}

/** `schedule_sla_milestones` after the commit (the scheduler only acts when the world runs, §10). */
async function scheduleMilestones(deps: ComplaintsDeps, worldId: string, complaintId: string): Promise<void> {
  if (!deps.milestones) return;
  const timerIds = MILESTONE_ORDER.map((milestone) => ({ kind: "SLA", timerId: milestoneTimerId(complaintId, milestone) }));
  try {
    await deps.milestones.schedule(worldId, timerIds);
  } catch (error) {
    deps.log.warn("complaints.schedule_failed", { worldId, errorName: error instanceof Error ? error.name : "UnknownError" });
  }
}
